///  One terrain raster solve result. On STATUS = OK every layer below is
///  present with exactly GRID_WIDTH * GRID_HEIGHT row-major entries. On any
///  other STATUS the result carries NO layers — never a partial raster.
class TRSResult {
  TRSResult._(this._bc, this._bcOffset);
  factory TRSResult(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<TRSResult> reader = _TRSResultReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  trsResultStatus get STATUS => trsResultStatus.fromValue(const fb.Int8Reader().vTableGet(_bc, _bcOffset, 4, 0));
  ///  On REFUSED or INVALID_INPUT: names the exact gap or defect. Empty on
  ///  OK.
  String? get ERROR_MESSAGE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  String? get errorMessage => ERROR_MESSAGE;
  ///  Output raster dimensions the layers are stated for, echoed from the
  ///  request.
  int get GRID_WIDTH => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 8, 0);
  int get gridWidth => GRID_WIDTH;
  int get GRID_HEIGHT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 10, 0);
  int get gridHeight => GRID_HEIGHT;
  ///  1 where the geometric ray from the emitter clears the obstruction
  ///  surface, else 0.
  List<int>? get VISIBLE_MASK => const fb.Uint8ListReader().vTableGetNullable(_bc, _bcOffset, 12);
  List<int>? get visibleMask => VISIBLE_MASK;
  ///  Complement of VISIBLE_MASK.
  List<int>? get OCCLUDED_MASK => const fb.Uint8ListReader().vTableGetNullable(_bc, _bcOffset, 14);
  List<int>? get occludedMask => OCCLUDED_MASK;
  ///  1 where LINK_MARGIN_DB > 0, else 0.
  List<int>? get POSITIVE_LINK_MASK => const fb.Uint8ListReader().vTableGetNullable(_bc, _bcOffset, 16);
  List<int>? get positiveLinkMask => POSITIVE_LINK_MASK;
  ///  Path classification of every cell from the dominant-edge diffraction
  ///  parameter — see trsPathClass.
  List<trsPathClass>? get PATH_CLASS => const fb.ListReader<trsPathClass>(trsPathClass.reader).vTableGetNullable(_bc, _bcOffset, 18);
  List<trsPathClass>? get pathClass => PATH_CLASS;
  ///  Total path loss including every applied term, dB (positive).
  List<double>? get PATH_LOSS_DB => const fb.ListReader<double>(fb.Float32Reader()).vTableGetNullable(_bc, _bcOffset, 20);
  List<double>? get pathLossDb => PATH_LOSS_DB;
  ///  Loss above free space — what the terrain cost the cell, dB.
  List<double>? get EXCESS_LOSS_DB => const fb.ListReader<double>(fb.Float32Reader()).vTableGetNullable(_bc, _bcOffset, 22);
  List<double>? get excessLossDb => EXCESS_LOSS_DB;
  ///  Link budget margin, dB.
  List<double>? get LINK_MARGIN_DB => const fb.ListReader<double>(fb.Float32Reader()).vTableGetNullable(_bc, _bcOffset, 24);
  List<double>? get linkMarginDb => LINK_MARGIN_DB;
  ///  ITU-R P.526-15 eq. (29) diffraction parameter v of the dominant edge.
  ///  Exactly -10.0 where no finite v exists (an unobstructed, Fresnel-clear
  ///  path) — the layer's stated no-finite-v encoding, carried verbatim so
  ///  the FlatBuffer and aligned-binary forms stay byte-comparable.
  List<double>? get DIFFRACTION_PARAMETER => const fb.ListReader<double>(fb.Float32Reader()).vTableGetNullable(_bc, _bcOffset, 26);
  List<double>? get diffractionParameter => DIFFRACTION_PARAMETER;
  ///  Specular ground-bounce contribution, dB. All zeros outside the
  ///  SPECULAR_SINGLE_BOUNCE tier.
  List<double>? get REFLECTION_CONTRIBUTION_DB => const fb.ListReader<double>(fb.Float32Reader()).vTableGetNullable(_bc, _bcOffset, 28);
  List<double>? get reflectionContributionDb => REFLECTION_CONTRIBUTION_DB;
  ///  Caller trace/correlation identifier copied from the request when
  ///  present.
  String? get TRACE_ID => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 30);
  String? get traceId => TRACE_ID;

  @override
  String toString() {
    return 'TRSResult{STATUS: ${STATUS}, errorMessage: ${errorMessage}, gridWidth: ${gridWidth}, gridHeight: ${gridHeight}, visibleMask: ${visibleMask}, occludedMask: ${occludedMask}, positiveLinkMask: ${positiveLinkMask}, pathClass: ${pathClass}, pathLossDb: ${pathLossDb}, excessLossDb: ${excessLossDb}, linkMarginDb: ${linkMarginDb}, diffractionParameter: ${diffractionParameter}, reflectionContributionDb: ${reflectionContributionDb}, traceId: ${traceId}}';
  }
}

class _TRSResultReader extends fb.TableReader<TRSResult> {
  const _TRSResultReader();

  @override
  TRSResult createObject(fb.BufferContext bc, int offset) =>
    TRSResult._(bc, offset);
}

class TRSResultBuilder {
  TRSResultBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(14);
  }

  int addStatus(trsResultStatus? STATUS) {
    fbBuilder.addInt8(0, STATUS?.value);
    return fbBuilder.offset;
  }
  int addErrorMessageOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addGridWidth(int? GRID_WIDTH) {
    fbBuilder.addUint32(2, GRID_WIDTH);
    return fbBuilder.offset;
  }
  int addGridHeight(int? GRID_HEIGHT) {
    fbBuilder.addUint32(3, GRID_HEIGHT);
    return fbBuilder.offset;
  }
  int addVisibleMaskOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addOccludedMaskOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addPositiveLinkMaskOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addPathClassOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addPathLossDbOffset(int? offset) {
    fbBuilder.addOffset(8, offset);
    return fbBuilder.offset;
  }
  int addExcessLossDbOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }
  int addLinkMarginDbOffset(int? offset) {
    fbBuilder.addOffset(10, offset);
    return fbBuilder.offset;
  }
  int addDiffractionParameterOffset(int? offset) {
    fbBuilder.addOffset(11, offset);
    return fbBuilder.offset;
  }
  int addReflectionContributionDbOffset(int? offset) {
    fbBuilder.addOffset(12, offset);
    return fbBuilder.offset;
  }
  int addTraceIdOffset(int? offset) {
    fbBuilder.addOffset(13, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

