  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
///  Terrain raster solve envelope.
class TRS {
  TRS._(this._bc, this._bcOffset);
  factory TRS(List<int> bytes) {
    final rootRef = fb.BufferContext.fromBytes(bytes);
    return reader.read(rootRef, 0);
  }

  static const fb.Reader<TRS> reader = _TRSReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  TRSRequest? get REQUEST => TRSRequest.reader.vTableGetNullable(_bc, _bcOffset, 4);
  TRSResult? get RESULT => TRSResult.reader.vTableGetNullable(_bc, _bcOffset, 6);

  @override
  String toString() {
    return 'TRS{REQUEST: ${REQUEST}, RESULT: ${RESULT}}';
  }
}

class _TRSReader extends fb.TableReader<TRS> {
  const _TRSReader();

  @override
  TRS createObject(fb.BufferContext bc, int offset) =>
    TRS._(bc, offset);
}

class TRSBuilder {
  TRSBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(2);
  }

  int addRequestOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addResultOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class TRSObjectBuilder extends fb.ObjectBuilder {
  final TRSRequestObjectBuilder? _REQUEST;
  final TRSResultObjectBuilder? _RESULT;

  TRSObjectBuilder({
    TRSRequestObjectBuilder? REQUEST,
    TRSResultObjectBuilder? RESULT,
  })
      : _REQUEST = REQUEST,
        _RESULT = RESULT;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? REQUESTOffset = _REQUEST?.getOrCreateOffset(fbBuilder);
    final int? RESULTOffset = _RESULT?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(2);
    fbBuilder.addOffset(0, REQUESTOffset);
    fbBuilder.addOffset(1, RESULTOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
